macro_rules! InferTy {
    () => {
        # [doc = " A placeholder for a type that hasn't been inferred yet."] # [doc = ""] # [doc = " E.g., if we have an empty array (`[]`), then we create a fresh"] # [doc = " type variable for the element type since we won't know until it's"] # [doc = " used what the element type is supposed to be."] # [derive (Clone , Copy , PartialEq , Eq , PartialOrd , Ord , Hash)] # [cfg_attr (feature = "nightly" , derive (Encodable_NoContext , Decodable_NoContext))] pub enum InferTy { # [doc = " A type variable."] TyVar (TyVid) , # [doc = " An integral type variable (`{integer}`)."] # [doc = ""] # [doc = " These are created when the compiler sees an integer literal like"] # [doc = " `1` that could be several different types (`u8`, `i32`, `u32`, etc.)."] # [doc = " We don't know until it's used what type it's supposed to be, so"] # [doc = " we create a fresh type variable."] IntVar (IntVid) , # [doc = " A floating-point type variable (`{float}`)."] # [doc = ""] # [doc = " These are created when the compiler sees an float literal like"] # [doc = " `1.0` that could be either an `f32` or an `f64`."] # [doc = " We don't know until it's used what type it's supposed to be, so"] # [doc = " we create a fresh type variable."] FloatVar (FloatVid) , # [doc = " A [`FreshTy`][Self::FreshTy] is one that is generated as a replacement"] # [doc = " for an unbound type variable. This is convenient for caching etc. See"] # [doc = " `rustc_infer::infer::freshen` for more details."] # [doc = ""] # [doc = " Compare with [`TyVar`][Self::TyVar]."] FreshTy (u32) , # [doc = " Like [`FreshTy`][Self::FreshTy], but as a replacement for [`IntVar`][Self::IntVar]."] FreshIntTy (u32) , # [doc = " Like [`FreshTy`][Self::FreshTy], but as a replacement for [`FloatVar`][Self::FloatVar]."] FreshFloatTy (u32) , }
    };
}

InferTy!()